<template><div><span v-if="!ids.length">未提供</span><p v-for="id in ids" :key="id" class="ui-two-line">{{names[id]||('名称未提供（'+id+'）')}}</p><span v-if="error" class="ui-error">{{error}}</span></div></template>
<script>import {uiRead} from '@/api/stage1-usability';import {managerSession} from '@/libs/manager-session';export default {props:{ids:{type:Array,default:()=>[]},purpose:{type:String,default:'eligibility'},storeId:String},data:()=>({names:{},error:'',ticket:0}),watch:{ids:{immediate:true,deep:true,handler(){this.reload();}},storeId(){this.reload();}},beforeDestroy(){this.ticket++;},methods:{async reload(){const ticket=++this.ticket,source=managerSession.snapshot();this.names={};this.error='';if(!this.ids.length)return;try{const names={};for(let page=1;page<=10000;page++){const value=await uiRead('/lookups/categories',{purpose:this.purpose,targetStore:this.storeId||undefined,pageNumber:page,pageSize:100});if(ticket!==this.ticket||!managerSession.sameSession(source))return;value.records.forEach(r=>{names[r.id]=r.path||r.name;});if(page*100>=value.total)break;}if(ticket===this.ticket)this.names=names;}catch(e){if(ticket===this.ticket)this.error=e.message;}}}};</script>
